    n = len(M)
    if n == 0:
        return 1
    A = [row[:] for row in M]
    if n == 1:
        return A[0][0]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k]:
                    A[k], A[i] = A[i], A[k]
                    sign = -sign
                    break
            else:
                return 0
        p = A[k][k]
        for i in range(k + 1, n):
            aik = A[i][k]
            for j in range(k + 1, n):
                A[i][j] = (p * A[i][j] - aik * A[k][j]) // prev
        prev = p
    return sign * A[n - 1][n - 1]

