from fractions import Fraction
def solve(M):
    n = len(M)
    if n == 0:
        return 1
    A = [[Fraction(x) for x in row] for row in M]
    det = Fraction(1)
    for k in range(n):
        piv = k
        while piv < n and A[piv][k] == 0:
            piv += 1
        if piv == n:
            return 0
        if piv != k:
            A[k], A[piv] = A[piv], A[k]
            det = -det
        det *= A[k][k]
        inv = A[k][k]
        for j in range(k, n):
            A[k][j] /= inv
        for i in range(k + 1, n):
            f = A[i][k]
            if f:
                for j in range(k, n):
                    A[i][j] -= f * A[k][j]
    return int(det)

