def solve(n):
    if n < 2:
        return 0
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve[i]:
            sieve[i*i:n:i] = b'\x00' * (((n - 1 - i*i) // i) + 1)
    return sum(sieve)

