import random

def solve(m):
    n = len(m)
    if n == 0:
        return 1
    a = [[int(x) for x in row] for row in m]
    if n == 1:
        return a[0][0]
    prev = 1
    sign = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            for r in range(k + 1, n):
                if a[r][k] != 0:
                    a[k], a[r] = a[r], a[k]
                    sign = -sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
        prev = a[k][k]
    return sign * a[n - 1][n - 1]

def det_fracfree(B):
    B = [list(map(int, row)) for row in B]
    n = len(B)
    if n == 0:
        return 1
    if n == 1:
        return B[0][0]
    prev = 1
    for k in range(n - 1):
        p = k
        while p < n and B[p][k] == 0:
            p += 1
        if p == n:
            return 0
        if p != k:
            B[k], B[p] = B[p], B[k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                B[i][j] = (B[i][j] * B[k][k] - B[i][k] * B[k][j]) // prev
        prev = B[k][k]
    return B[n - 1][n - 1]

def det_cof(M):
    n = len(M)
    if n == 0:
        return 1
    if n == 1:
        return M[0][0]
    a = M[0]
    res = 0
    for j in range(n):
        sub = [row[:j] + row[j + 1:] for row in M[1:]]
        res += ((-1) ** j) * a[j] * det_cof(sub)
    return res

